"""The schedule a retrying client would follow. See task.md."""

from __future__ import annotations

# A recorded response: {"status": int, "retry_after_ms": int}  (the second key
# is optional).
Response = dict

# A planned attempt: {"number": int, "start_ms": int, "delay_ms": int}.
Attempt = dict


RETRYABLE = {429, 503, 500, 502}
TERMINAL = {200, 400, 401, 404}


class PolicyError(ValueError):
    """Raised for a policy or deadline that cannot describe a schedule."""


def _factor_ratio(factor):
    if isinstance(factor, list):
        num, den = factor
        return num, den
    return factor, 1


def _validate(policy: dict, deadline_ms: int) -> None:
    if policy["base_ms"] <= 0:
        raise PolicyError("base_ms must be strictly positive")

    num, den = _factor_ratio(policy["factor"])
    if den <= 0 or num < den:
        raise PolicyError("factor must be at least 1")

    if policy["max_attempts"] < 1:
        raise PolicyError("max_attempts must be at least 1")

    if deadline_ms < 0:
        raise PolicyError("deadline_ms must not be negative")


def _computed_delay(policy: dict, n: int) -> int:
    """Backoff delay before attempt n (n >= 2)."""
    num, den = _factor_ratio(policy["factor"])
    k = n - 2
    raw_num = policy["base_ms"] * num**k
    raw_den = den**k
    backed = raw_num // raw_den
    return min(backed, policy["max_delay_ms"])


def plan(policy: dict, responses: list[Response], deadline_ms: int) -> list[Attempt]:
    """Return the attempts a client under `policy` would make against `responses`."""
    _validate(policy, deadline_ms)

    attempts: list[Attempt] = []
    start_ms = 0
    next_delay = 0
    n = 1

    while n <= policy["max_attempts"]:
        if n - 1 >= len(responses):
            break
        if n > 1:
            start_ms += next_delay
        if start_ms >= deadline_ms:
            break

        delay_ms = 0 if n == 1 else next_delay
        attempts.append({"number": n, "start_ms": start_ms, "delay_ms": delay_ms})

        response = responses[n - 1]
        status = response["status"]

        if status == 200 or status not in RETRYABLE:
            break

        if "retry_after_ms" in response:
            next_delay = response["retry_after_ms"]
        else:
            next_delay = _computed_delay(policy, n + 1)

        n += 1

    return attempts
